graphql.query:
query ($boardId: [ID!]) {
  boards(ids: $boardId) {
    id
    name
    groups { id title }
    # The board's own column definitions. A formula lives ONLY here — the copy of
    # a column that rides inside every item carries its title and type and
    # nothing else — and `settings_str` is the JSON holding the expression:
    #   {"formula": "{numeric_mkl3sp} + 5"}   (references are column IDs)
    # It is the deprecated spelling of the typed `settings` object, and it is
    # asked for deliberately: it exists in every API version this export runs
    # against, while `settings` does not. The importer reads either shape.
    columns { id title type settings_str }
    items_page(limit: 500) {
      cursor
      items {
        id
        name
        group { id title }
        column_values {
          id
          type
          column { title }
          text
          value
          ... on FileValue { files { ... on FileAssetValue { asset_id } } }
          # Three types do not answer in `text` at all, and asking only for it
          # is what made them arrive empty on every single item:
          #   board_relation — "the text and value fields always return null"
          #   mirror         — the mirrored content lives in display_value
          #   formula        — "the computed result is returned in display_value;
          #                     the text and value fields are not populated"
          ... on BoardRelationValue { display_value linked_item_ids linked_items { id name } }
          ... on MirrorValue { display_value }
          # ⚠ monday allows at most FIVE formula columns per request (and 10,000
          # formula values a minute). A board with more than five gets an error or
          # empty strings back: export it twice, each run naming a different set
          # of column `ids`, or drop this line and accept that the formulas —
          # which are computed, never stored — do not come across.
          ... on FormulaValue { display_value }
        }
        assets { id name public_url }
        subitems {
          id
          name
          column_values {
            id type column { title } text value
            ... on FileValue { files { ... on FileAssetValue { asset_id } } }
            ... on BoardRelationValue { display_value linked_item_ids linked_items { id name } }
            ... on MirrorValue { display_value }
            ... on FormulaValue { display_value }
          }
          # A file cell names its asset, and the asset — its real name and the link
          # that can actually be fetched — is carried by the ROW the cell sits on.
          # Asked for on the items and not on their sub-items, every file attached to
          # a sub-item arrived as a bare name with nothing behind it.
          assets { id name public_url }
          updates {
            id body text_body created_at
            creator { name email }
            replies { id body text_body created_at creator { name email } }
            assets { id name public_url }
          }
        }
        updates {
          id body text_body created_at
          creator { name email }
          replies { id body text_body created_at creator { name email } }
          assets { id name public_url }
        }
      }
    }
  }
}

